-- Rebuild Medina Book 4 lesson 7 strictly from the supplied Arabic sharh.
-- Canonical PDF pages: 28-31. DOC text was used only for extraction and checked against the PDF.
begin;

do $migration$
declare
  existing_count integer;
begin
  select count(*) into existing_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '7';
  if existing_count <> 5 then
    raise exception 'Expected 5 Book 4 lesson 7 rules, found %', existing_count;
  end if;
end $migration$;

with incoming(sort_order, title, content, summary, rule_ar) as (
  values
    (1, 'بَابُ اِفْعَلَّ (порода اِفْعَلَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْعَلَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ. يَأْتِي هَذَا الْبَابُ فِي الْأَلْوَانِ وَالْعُيُوبِ، وَلَا يَكُونُ إِلَّا لَازِمًا.</span><p class="rule-study-text">Порода اِفْعَلَّ содержит соединительную хамзу и удвоение, выражает усиленное проявление признака, употребляется для цветов и недостатков и бывает только непереходной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">حَرْفَا الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالتَّضْعِيفُ</span><span class="rule-term-ru">добавочные элементы — соединительная хамза и удвоение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِفْعِلَالٌ</span><span class="rule-term-ru">масдар по модели اِفْعِلَالٌ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُبَالَغَةُ</span><span class="rule-term-ru">усиленное проявление признака</span></div><div class="rule-meaning-card rule-term-subject"><span class="rule-term-ar ar-tone-subject" dir="rtl" lang="ar">الْأَلْوَانُ وَالْعُيُوبُ</span><span class="rule-term-ru">цвета и недостатки</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِحْمَرَّ</span><span class="rule-example-ru">сильно покраснел</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِصْفَرَّ</span><span class="rule-example-ru">сильно пожелтел</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِغْبَرَّ</span><span class="rule-example-ru">покрылся пылью, стал пыльного цвета</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِعْوَجَّ</span><span class="rule-example-ru">сильно искривился</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Образование масдара</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِحْمَرَّ ← اِحْمِرَارٌ</span><span class="rule-example-ru">покраснел → покраснение</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِغْبَرَّ ← اِغْبِرَارٌ</span><span class="rule-example-ru">покрылся пылью → запыление</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие и исходная форма</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِصْفَرَّ</span><span class="rule-table-ru">пожелтел</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَصْفَرُّ</span><span class="rule-table-ru">желтеет</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِصْفِرَارٌ</span><span class="rule-table-ru">пожелтение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُصْفَرٌّ، أَصْلُهُ: مُصْفَرِرٌ</span><span class="rule-table-ru">желтеющий; исходная форма — مُصْفَرِرٌ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِعْوَجَّ</span><span class="rule-table-ru">искривился</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَعْوَجُّ</span><span class="rule-table-ru">искривляется</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِعْوِجَاجٌ</span><span class="rule-table-ru">искривление</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُعْوَجٌّ، أَصْلُهُ: مُعْوَجِجٌ</span><span class="rule-table-ru">искривляющийся; исходная форма — مُعْوَجِجٌ</span></td></tr></tbody></table></div></div></div>', 'Порода اِفْعَلَّ содержит соединительную хамзу и удвоение, выражает усиленное проявление признака, употребляется для цветов и недостатков и бывает только непереходной.', 'بَابُ اِفْعَلَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ. يَأْتِي هَذَا الْبَابُ فِي الْأَلْوَانِ وَالْعُيُوبِ، وَلَا يَكُونُ إِلَّا لَازِمًا.'),
    (2, 'بَابُ اِفْعَالَّ (порода اِفْعَالَّ)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">بَابُ اِفْعَالَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالْأَلِفِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِيلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ. يَأْتِي هَذَا الْبَابُ فِي الْأَلْوَانِ فَقَطْ، وَلَا يَكُونُ إِلَّا لَازِمًا.</span><p class="rule-study-text">Порода اِفْعَالَّ содержит соединительную хамзу, добавочную алиф и удвоение. Она усиливает значение цвета, употребляется только для цветов и бывает только непереходной.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">أَحْرُفُ الزِّيَادَةِ: هَمْزَةُ الْوَصْلِ وَالْأَلِفُ وَالتَّضْعِيفُ</span><span class="rule-term-ru">добавочные элементы — соединительная хамза, алиф и удвоение</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ: اِفْعِيلَالٌ</span><span class="rule-term-ru">масдар по модели اِفْعِيلَالٌ</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمُبَالَغَةُ فِي الْأَلْوَانِ فَقَطْ</span><span class="rule-term-ru">усиленное проявление только цвета</span></div><div class="rule-meaning-card rule-term-verb"><span class="rule-term-ar ar-tone-verb" dir="rtl" lang="ar">لَازِمٌ</span><span class="rule-term-ru">порода бывает только непереходной</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Все примеры шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِحْمَارَّ</span><span class="rule-example-ru">стал насыщенно-красным</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِصْفَارَّ</span><span class="rule-example-ru">стал насыщенно-жёлтым</span></div><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِدْهَامَّ</span><span class="rule-example-ru">стал очень тёмным</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Образование масдара</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">اِحْمَارَّ ← اِحْمِيرَارٌ</span><span class="rule-example-ru">стал насыщенно-красным → интенсивное покраснение</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Производные формы шарха</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمَاضِي</span><span class="rule-table-ru">прошедшее</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمُضَارِعُ</span><span class="rule-table-ru">настояще-будущее</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ</span><span class="rule-table-ru">масдар</span></th><th><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">اسْمُ الْفَاعِلِ</span><span class="rule-table-ru">действующее причастие и исходная форма</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِحْمَارَّ</span><span class="rule-table-ru">стал насыщенно-красным</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَحْمَارُّ</span><span class="rule-table-ru">становится насыщенно-красным</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِحْمِيرَارٌ</span><span class="rule-table-ru">интенсивное покраснение</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُحْمَارٌّ، أَصْلُهُ: مُحْمَارِرٌ</span><span class="rule-table-ru">становящийся насыщенно-красным; исходная форма — مُحْمَارِرٌ</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">اِبْيَاضَّ</span><span class="rule-table-ru">стал насыщенно-белым</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَبْيَاضُّ</span><span class="rule-table-ru">становится насыщенно-белым</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">اِبْيِيضَاضٌ</span><span class="rule-table-ru">интенсивное побеление</span></td><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">مُبْيَاضٌّ، أَصْلُهُ: مُبْيَاضِضٌ</span><span class="rule-table-ru">становящийся насыщенно-белым; исходная форма — مُبْيَاضِضٌ</span></td></tr></tbody></table></div></div></div>', 'Порода اِفْعَالَّ содержит соединительную хамзу, добавочную алиф и удвоение. Она усиливает значение цвета, употребляется только для цветов и бывает только непереходной.', 'بَابُ اِفْعَالَّ مَزِيدٌ بِهَمْزَةِ الْوَصْلِ وَالْأَلِفِ وَالتَّضْعِيفِ، وَمَصْدَرُهُ عَلَى وَزْنِ اِفْعِيلَالٍ، وَمَعْنَاهُ الْمُبَالَغَةُ. يَأْتِي هَذَا الْبَابُ فِي الْأَلْوَانِ فَقَطْ، وَلَا يَكُونُ إِلَّا لَازِمًا.'),
    (3, 'رَأَى (два значения и управление глагола رَأَى)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">رَأَى نَوْعَانِ: بَصَرِيَّةٌ تَنْصِبُ مَفْعُولًا وَاحِدًا، وَقَلْبِيَّةٌ بِمَعْنَى عَلِمَ تَنْصِبُ مَفْعُولَيْنِ.</span><p class="rule-study-text">Зрительное رَأَى означает «увидеть» и требует одно дополнение. Рَأَى внутреннего восприятия означает «узнать, считать» и требует два дополнения.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два вида رَأَى</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">النَّوْعُ</span><span class="rule-table-ru">вид</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَعْنَى وَالْعَمَلُ</span><span class="rule-table-ru">значение и управление</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">بَصَرِيَّةٌ</span><span class="rule-table-ru">зрительное восприятие</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ مَفْعُولًا وَاحِدًا</span><span class="rule-table-ru">ставит одно дополнение в винительный падеж</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَأَيْتُ الطَّالِبَ.</span><span class="rule-table-ru">Я увидел ученика.</span></td></tr><tr><td><span class="rule-table-ar ar-tone-subject" dir="rtl" lang="ar">قَلْبِيَّةٌ بِمَعْنَى عَلِمَ</span><span class="rule-table-ru">внутреннее восприятие в значении «узнал, счёл»</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ مَفْعُولَيْنِ</span><span class="rule-table-ru">ставит два дополнения в винительный падеж</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَأَيْتُ الْعِلْمَ نُورًا.</span><span class="rule-table-ru">Я счёл знание светом.</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два дополнения رَأَى الْقَلْبِيَّةُ</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْجُمْلَةُ</span><span class="rule-table-ru">предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ الْأَوَّلُ</span><span class="rule-table-ru">первое дополнение</span></th><th><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْمَفْعُولُ بِهِ الثَّانِي</span><span class="rule-table-ru">второе дополнение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">رَأَى مُحَمَّدٌ الْحَقَّ وَاضِحًا.</span><span class="rule-table-ru">Мухаммад счёл истину ясной.</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">الْحَقَّ</span><span class="rule-table-ru">истину — первое дополнение</span></td><td><span class="rule-table-ar ar-tone-nasb" dir="rtl" lang="ar">وَاضِحًا</span><span class="rule-table-ru">ясной — второе дополнение</span></td></tr></tbody></table></div></div></div>', 'Зрительное رَأَى означает «увидеть» и требует одно дополнение. Рَأَى внутреннего восприятия означает «узнать, считать» и требует два дополнения.', 'رَأَى نَوْعَانِ: بَصَرِيَّةٌ تَنْصِبُ مَفْعُولًا وَاحِدًا، وَقَلْبِيَّةٌ بِمَعْنَى عَلِمَ تَنْصِبُ مَفْعُولَيْنِ.'),
    (4, 'مَا الْمَصْدَرِيَّةُ (масдарная частица مَا)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-particle" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ هِيَ الَّتِي تُؤَوَّلُ مَعَ مَا بَعْدَهَا بِمَصْدَرٍ صَرِيحٍ. وَأَحْرُفُ الْمَصْدَرِ هِيَ: أَنْ، وَأَنَّ، وَمَا، وَكَيْ، وَلَوْ.</span><p class="rule-study-text">Масдарная مَا вместе с последующим выражением преобразуется в явный масдар. Его синтаксическое место определяется положением всей конструкции в предложении.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Термины и русский смысл</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-particle"><span class="rule-term-ar ar-tone-particle" dir="rtl" lang="ar">مَا الْمَصْدَرِيَّةُ</span><span class="rule-term-ru">масдарная مَا</span></div><div class="rule-meaning-card rule-term-structure"><span class="rule-term-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ</span><span class="rule-term-ru">конструкция, истолкованная как масдар</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">الْمَصْدَرُ الصَّرِيحُ</span><span class="rule-term-ru">явный масдар, которым заменяется конструкция</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Примеры и синтаксическое место</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">исходное предложение и перевод</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَصْدَرُ الْمُؤَوَّلُ وَمَحَلُّهُ</span><span class="rule-table-ru">конструкция и её место</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّقْدِيرُ</span><span class="rule-table-ru">замена явным масдаром</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">وَجَدْتُ قَلَمِي بَعْدَ مَا انْتَهَتِ الصَّلَاةُ.</span><span class="rule-table-ru">Я нашёл свою ручку после того, как закончилась молитва.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَا انْتَهَتِ الصَّلَاةُ: فِي مَحَلِّ جَرٍّ مُضَافٌ إِلَيْهِ</span><span class="rule-table-ru">в родительном месте второй части идафы</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">بَعْدَ انْتِهَاءِ الصَّلَاةِ</span><span class="rule-table-ru">после окончания молитвы</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">أَتَكَلَّمُ الْفَرَنْسِيَّةَ كَمَا يَتَكَلَّمُ أَهْلُ فَرَنْسَا.</span><span class="rule-table-ru">Я говорю по-французски так, как говорят жители Франции.</span></td><td><span class="rule-table-ar ar-tone-jarr" dir="rtl" lang="ar">مَا يَتَكَلَّمُ: فِي مَحَلِّ جَرٍّ بِحَرْفِ الْجَرِّ الْكَافِ</span><span class="rule-table-ru">в родительном месте после предлога كَـ</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">كَتَكَلُّمِ أَهْلِ فَرَنْسَا</span><span class="rule-table-ru">как речь жителей Франции</span></td></tr><tr><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">يَسُرُّ الْمَرْءَ مَا ذَهَبَ اللَّيَالِي.</span><span class="rule-table-ru">Человека радует уход ночей.</span></td><td><span class="rule-table-ar ar-tone-raf" dir="rtl" lang="ar">مَا ذَهَبَ: فِي مَحَلِّ رَفْعٍ فَاعِلٌ</span><span class="rule-table-ru">в именительном месте исполнителя</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">ذَهَابُ اللَّيَالِي</span><span class="rule-table-ru">уход ночей</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Коранический пример шарха</span><div class="rule-example-list"><div class="rule-example-card rule-term-default"><span class="rule-example-ar ar-tone-default rule-quran-ar" dir="rtl" lang="ar">﴿فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡفُرُونَ﴾</span><span class="rule-example-ru">«Вкусите наказание за то, что вы не веровали»: بِمَا كُنْتُمْ تَكْفُرُونَ означает بِكَوْنِكُمْ كَافِرِينَ — «за то, что вы были неверующими».</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">أَحْرُفُ الْمَصْدَرِ — масдарные частицы</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">الْحَرْفُ</span><span class="rule-table-ru">частица</span></th><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى بِالرُّوسِيَّةِ</span><span class="rule-table-ru">русское пояснение</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنْ</span><span class="rule-table-ru">масдарная частица أَنْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنْ</span><span class="rule-table-ru">образует конструкцию, равную масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">أَنَّ</span><span class="rule-table-ru">масдарная частица أَنَّ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">أَنَّ</span><span class="rule-table-ru">образует конструкцию, равную масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">масдарная частица مَا</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">مَا</span><span class="rule-table-ru">образует конструкцию, равную масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">كَيْ</span><span class="rule-table-ru">масдарная частица كَيْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">كَيْ</span><span class="rule-table-ru">образует конструкцию, равную масдару</span></td></tr><tr><td><span class="rule-table-ar ar-tone-particle" dir="rtl" lang="ar">لَوْ</span><span class="rule-table-ru">масдарная частица لَوْ</span></td><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">لَوْ</span><span class="rule-table-ru">образует конструкцию, равную масдару</span></td></tr></tbody></table></div></div></div>', 'Масдарная مَا вместе с последующим выражением преобразуется в явный масдар. Его синтаксическое место определяется положением всей конструкции в предложении.', 'مَا الْمَصْدَرِيَّةُ هِيَ الَّتِي تُؤَوَّلُ مَعَ مَا بَعْدَهَا بِمَصْدَرٍ صَرِيحٍ. وَأَحْرُفُ الْمَصْدَرِ هِيَ: أَنْ، وَأَنَّ، وَمَا، وَكَيْ، وَلَوْ.'),
    (5, 'عَسَى (глагол надежды или опасения عَسَى)', '<div class="rule-study"><div class="rule-study-card"><span class="rule-card-kicker">Правило</span><span class="rule-main-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى فِعْلٌ مَاضٍ جَامِدٌ يَدُلُّ عَلَى التَّرَجِّي أَوِ الْإِشْفَاقِ. تَعْمَلُ عَمَلَ كَانَ فَتَرْفَعُ الِاسْمَ وَتَنْصِبُ الْخَبَرَ، وَخَبَرُهَا فِعْلٌ مُضَارِعٌ يَقْتَرِنُ بِأَنْ كَثِيرًا. تَكُونُ نَاقِصَةً، أَوْ تَامَّةً، وَيَجُوزُ الْوَجْهَانِ إِذَا تَقَدَّمَ الِاسْمُ عَلَيْهَا.</span><p class="rule-study-text">عَسَى — неизменяемый по времени глагол прошедшей формы со значением надежды либо опасения. Он может быть неполным или полным; при вынесенном вперёд имени допустимы оба разбора.</p></div><div class="rule-study-card"><span class="rule-card-kicker">Два значения عَسَى</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْمَعْنَى</span><span class="rule-table-ru">значение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">التَّفْسِيرُ</span><span class="rule-table-ru">пояснение шарха</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">التَّرَجِّي</span><span class="rule-table-ru">надежда</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى الطَّالِبُ أَنْ يَنْجَحَ.</span><span class="rule-table-ru">Возможно, ученик успешно сдаст.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُرْجَى أَنْ يَنْجَحَ</span><span class="rule-table-ru">надеются, что он преуспеет</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْإِشْفَاقُ</span><span class="rule-table-ru">опасение</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى الْمَرِيضُ أَنْ يَمُوتَ.</span><span class="rule-table-ru">Есть опасение, что больной умрёт.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">يُخْشَى أَنْ يَمُوتَ</span><span class="rule-table-ru">опасаются, что он умрёт</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Управление عَسَى</span><div class="rule-meaning-grid"><div class="rule-meaning-card rule-term-raf"><span class="rule-term-ar ar-tone-raf" dir="rtl" lang="ar">تَرْفَعُ الِاسْمَ</span><span class="rule-term-ru">поднимает имя в именительный падеж</span></div><div class="rule-meaning-card rule-term-nasb"><span class="rule-term-ar ar-tone-nasb" dir="rtl" lang="ar">تَنْصِبُ الْخَبَرَ</span><span class="rule-term-ru">ставит сказуемое в винительный падеж</span></div><div class="rule-meaning-card rule-term-predicate"><span class="rule-term-ar ar-tone-predicate" dir="rtl" lang="ar">خَبَرُهَا فِعْلٌ مُضَارِعٌ يَقْتَرِنُ بِأَنْ كَثِيرًا</span><span class="rule-term-ru">её сказуемое — глагол настояще-будущего времени, часто с أَنْ</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Три положения عَسَى</span><div class="tbl-wrap"><table><thead><tr><th><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">الْحَالَةُ</span><span class="rule-table-ru">положение</span></th><th><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الْمِثَالُ</span><span class="rule-table-ru">пример и перевод</span></th><th><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">الْحُكْمُ</span><span class="rule-table-ru">грамматический результат</span></th></tr></thead><tbody><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">نَاقِصَةٌ</span><span class="rule-table-ru">неполный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى اللَّهُ أَنْ يَغْفِرَ لَنَا. عَسِيتُ أَنْ أَنْجَحَ.</span><span class="rule-table-ru">Возможно, Аллах простит нас. Возможно, я преуспею.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">لَا تَكْتَفِي بِمَرْفُوعِهَا</span><span class="rule-table-ru">не ограничивается своим именем и требует сказуемое</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">تَامَّةٌ</span><span class="rule-table-ru">полный глагол</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى أَنْ يَغْفِرَ اللَّهُ لَنَا. عَسَى أَنْ أَنْجَحَ.</span><span class="rule-table-ru">Возможно, Аллах простит нас. Возможно, я преуспею.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">تَكْتَفِي بِمَرْفُوعِهَا</span><span class="rule-table-ru">ограничивается своим подлежащим</span></td></tr><tr><td><span class="rule-table-ar ar-tone-structure" dir="rtl" lang="ar">جَوَازُ التَّمَامِ وَالنُّقْصَانِ</span><span class="rule-table-ru">допустимы полный и неполный разборы</span></td><td><span class="rule-table-ar ar-tone-verb" dir="rtl" lang="ar">الطَّالِبُ عَسَى أَنْ يَنْجَحَ.</span><span class="rule-table-ru">Возможно, ученик преуспеет.</span></td><td><span class="rule-table-ar ar-tone-predicate" dir="rtl" lang="ar">إِذَا تَقَدَّمَ الِاسْمُ عَلَيْهَا</span><span class="rule-table-ru">когда имя поставлено перед عَسَى</span></td></tr></tbody></table></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: عَسَى الطَّالِبُ أَنْ يَنْجَحَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى: فِعْلٌ مَاضٍ نَاقِصٌ مَبْنِيٌّ عَلَى الْفَتْحَةِ الْمُقَدَّرَةِ.</span><span class="rule-example-ru">عَسَى — неполный глагол прошедшей формы, неизменяемый на подразумеваемой фатхе.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">الطَّالِبُ: اسْمُ عَسَى مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الطَّالِبُ — имя عَسَى в именительном падеже; показатель — явная дамма.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">أَنْ يَنْجَحَ: الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ نَصْبٍ خَبَرُ عَسَى.</span><span class="rule-example-ru">أَنْ يَنْجَحَ — истолкованный масдар в винительном месте сказуемого عَسَى.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Полный إِعْرَابُ: عَسَى أَنْ يَنْجَحَ الطَّالِبُ</span><div class="rule-example-list"><div class="rule-example-card rule-term-verb"><span class="rule-example-ar ar-tone-verb" dir="rtl" lang="ar">عَسَى: فِعْلٌ مَاضٍ تَامٌّ مَبْنِيٌّ عَلَى الْفَتْحَةِ الْمُقَدَّرَةِ.</span><span class="rule-example-ru">عَسَى — полный глагол прошедшей формы, неизменяемый на подразумеваемой фатхе.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">أَنْ يَنْجَحَ: الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ رَفْعٍ فَاعِلُ عَسَى.</span><span class="rule-example-ru">أَنْ يَنْجَحَ — истолкованный масдар в именительном месте исполнителя عَسَى.</span></div><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ: فَاعِلٌ لِـيَنْجَحَ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ.</span><span class="rule-example-ru">الطَّالِبُ — исполнитель глагола يَنْجَحَ в именительном падеже с явной даммой.</span></div></div></div><div class="rule-study-card"><span class="rule-card-kicker">Два разбора: الطَّالِبُ عَسَى أَنْ يَنْجَحَ</span><div class="rule-example-list"><div class="rule-example-card rule-term-subject"><span class="rule-example-ar ar-tone-subject" dir="rtl" lang="ar">الطَّالِبُ: مُبْتَدَأٌ مَرْفُوعٌ، وَعَلَامَةُ رَفْعِهِ الضَّمَّةُ الظَّاهِرَةُ، وَخَبَرُهُ جُمْلَةُ عَسَى أَنْ يَنْجَحَ.</span><span class="rule-example-ru">الطَّالِبُ — подлежащее в именительном падеже с явной даммой; его сказуемое — всё предложение عَسَى أَنْ يَنْجَحَ.</span></div><div class="rule-example-card rule-term-nasb"><span class="rule-example-ar ar-tone-nasb" dir="rtl" lang="ar">يَجُوزُ إِعْرَابُ عَسَى نَاقِصَةً بِتَقْدِيرِ اسْمِهَا ضَمِيرًا مُسْتَتِرًا تَقْدِيرُهُ هُوَ، وَالْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ نَصْبٍ خَبَرُهَا.</span><span class="rule-example-ru">Можно разобрать عَسَى как неполный глагол: его имя — скрытое местоимение «он», а истолкованный масдар занимает винительное место сказуемого.</span></div><div class="rule-example-card rule-term-raf"><span class="rule-example-ar ar-tone-raf" dir="rtl" lang="ar">وَيَجُوزُ إِعْرَابُهَا تَامَّةً بِعَدَمِ تَقْدِيرِ الضَّمِيرِ، فَيَكُونُ الْمَصْدَرُ الْمُؤَوَّلُ فِي مَحَلِّ رَفْعٍ فَاعِلٌ.</span><span class="rule-example-ru">Можно разобрать её как полный глагол без подразумеваемого местоимения; тогда истолкованный масдар занимает именительное место исполнителя.</span></div></div></div></div>', 'عَسَى — неизменяемый по времени глагол прошедшей формы со значением надежды либо опасения. Он может быть неполным или полным; при вынесенном вперёд имени допустимы оба разбора.', 'عَسَى فِعْلٌ مَاضٍ جَامِدٌ يَدُلُّ عَلَى التَّرَجِّي أَوِ الْإِشْفَاقِ. تَعْمَلُ عَمَلَ كَانَ فَتَرْفَعُ الِاسْمَ وَتَنْصِبُ الْخَبَرَ، وَخَبَرُهَا فِعْلٌ مُضَارِعٌ يَقْتَرِنُ بِأَنْ كَثِيرًا. تَكُونُ نَاقِصَةً، أَوْ تَامَّةً، وَيَجُوزُ الْوَجْهَانِ إِذَا تَقَدَّمَ الِاسْمُ عَلَيْهَا.')
)
update public.rules as r
set title = incoming.title,
    content = incoming.content,
    rule_kind = 'rule',
    summary = incoming.summary,
    rule_ar = incoming.rule_ar
from incoming
where r.course_name = 'Мединский курс (Том 4)'
  and r.lesson_number = '7'
  and r.sort_order = incoming.sort_order;

delete from public.rule_sources
where rule_id in (
  select id from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '7'
);

