insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'مَا الْمَصْدَرِيَّةُ
ما المصدريَّةُ ، هي : التي تُؤَوَّلُ مع ما بعدها بمصدر صريح .
نحو : وجدت قلمي بعد ما انتهت الصلاة ، المصدر المؤَوَّل ( ما انتهت ) في محل جر مضاف إليه ، والتقدير : بعد انتهاء الصلاة .
ونحو : أتكلم الفرنسية كما يتكلم أهل فرنسا ، المصدر المؤول ( ما يتكلَّم ) في محل جر بحرف الجر الكاف ، والتقدير : كتكلُّمِ أهلِ فرنسا .
ونحو : يَسُرُّ المرءَ ما ذهبَ اللَّيَالي ، المصدر المؤوّل ( ما ذهب ) في محل رفع فاعل ، والتقدير : ذَهَابُ اللَّيالي .
ومنه قوله تعالى : ﴿ فَذُوقُوا الْعَذَابَ بِمَا كُنْتُمْ تَكْفُرُونَ ﴾ أي : بكونكم كافرين .
وأحرف المصدر, هي : أنْ , وأنَّ , ومَا , وكَيْ , ولَوْ .', 29, 30, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '7' and sort_order = 4;

insert into public.rule_sources (rule_id, source_document, source_text, source_page_from, source_page_to, sort_order)
select id, 'Sharkh_Medinskiy_4.pdf', 'عَسَى
عسى : فعلٌ ماضٍ جامدٌ .
معناها:
1- التَّرَجِّي : نحو : عَسَى الطالبُ أَنْ ينجحَ ، أي : يُرْجَى أن ينجح .
2- الإِشْفَاقُ : نحو : عَسَى المريضُ أَنْ يموتَ ، أي : يُخْشَى أن يموت .
عملُها :
تعملُ عملَ كان ، ترفع الاسم وتنصب الخبر ، وخبرها فعل مضارع يقترن بأنْ كثيرا .
أنوعها :
1- نَاقِصَةٌ : أي لا تكتفي بِمرفوعها ، نحو : عَسَى اللهُ أَنْ يَغْفِرَ لَنَا  . عسيتُ أن أنجح .
2- تَامَّةٌ : أي تكتفي بِمرفوعها ، نحو : عسى أن يغفر اللهُ لنا . عَسَى أَنْ أنجحَ .
3- جَوَازُ الأَمْرَيْنِ التَّمَامُ ، والنُّقْصَانُ : وذلك إذا تقدم الاسم عليها , نحو :       الطَّالبُ عَسَى أَنْ ينجحَ ، فيجوز :
أ- اعتبارها ناقصة ، وذلك بتقدير ضمير مستتر يعود على الطالب ، نحو :
الطَّالبُ عسى أن ينجحَ ، اسم عسى : ضمير مستتر تقديره هو .
ب- اعتبارها تامَّة : وذلك بعدم تقدير الضمير .
وفي الحالتين يعربُ الاسمُ المتقدِّمُ مبتدأً خبره جملة عسى .
الإعراب :
عسى الطَّالبُ أن ينجحَ .
عسى : فعل ماض ناقص مبني على الفتحة المقدرة .
الطالبُ : اسم عسى مرفوع وعلامة رفعه الضمة الظاهرة .
أن ينجحَ : المصدر المؤول في محل نصب خبر عسى .
عسى أن ينجحَ الطالبُ .
عسى : فعل ماض تام مبني على الفتحة المقدرة .
أن ينجحَ : المصدر المؤول في محل رفع فاعل عسى .
الطالبُ : فاعل لـ ( ينجح ) مرفوع وعلامة رفعه الضمة الظاهرة .
الطالبُ عسى أن ينجحَ .
الطالبُ : مبتدأ مرفوع وعلامة رفعه الضمة الظاهرة, خبره جملة ( عسى أن ينجحَ ) .
عسى : • يجوز إعرابها ناقصة وذلك بتقدير اسمها : ضمير مستتر تقديره ( هو ) .
والمصدر المؤوَّل في محلِّ نصب خبرها .
• ويجوز إعرابها تامَّة,وذلك بعدم تقدير الضمير فيكون المصدر المؤوَّل في محل رفع فاعل .', 30, 31, 1
from public.rules
where course_name = 'Мединский курс (Том 4)' and lesson_number = '7' and sort_order = 5;

do $migration$
declare
  updated_count integer;
  source_count integer;
begin
  select count(*) into updated_count
  from public.rules
  where course_name = 'Мединский курс (Том 4)' and lesson_number = '7' and rule_ar is not null and btrim(rule_ar) <> '';
  select count(*) into source_count
  from public.rule_sources rs
  join public.rules r on r.id = rs.rule_id
  where r.course_name = 'Мединский курс (Том 4)' and r.lesson_number = '7';
  if updated_count <> 5 or source_count <> 5 then
    raise exception 'Book 4 lesson 7 QA failed: rules %, sources %', updated_count, source_count;
  end if;
end $migration$;

commit;
